        ),
        DropdownInput(
            name="direction",
            display_name="运动方向",
            info="POSITIVE=正方向, NEGATIVE=负方向, NONE=停止点动",
            options=DIRECTIONS,
            value="POSITIVE",
        ),
        IntInput(
            name="joint_count",
            display_name="关节数量",
            info="模型关节数量，用于生成关节/零空间点动向量",
            value=7,
        ),
        StrInput(
            name="nullspace_vector",
            display_name="零空间方向向量",
            info="NULLSPACE 时使用，长度需等于关节数量，如: 1,0,0,0,0,0,0",
            value="1,0,0,0,0,0,0",
        ),
