            name="speed",
            display_name="点动速度",
            info="点动速度，关节单位 rad/s，笛卡尔单位按后端 MoveJog 解释",
            value=0.005,
        ),
        FloatInput(
            name="timeout",
            display_name="命令有效期(s)",
            info="单次点动命令有效期，建议大于上位机重复下发周期",
            value=0.3,
        ),
