# ---- 4. 语义缓存（核心加速层） ----

class RocosSemanticCache(Component):
    """语义→指令缓存: 高频指令跳过LLM推理，8s→0.5s"""

    display_name: str = "ROCOS 语义缓存"
    description: str = (
        "语义指令缓存加速器。工作原理:\n"
        "1. 查询: 输入自然语言指令 → 检查是否已缓存 → 命中则直接返回 API 调用参数\n"
        "2. 学习: 每次执行后调用 learn 模式，累积语义→指令映射\n"
        "频率 ≥3 次才缓存命中，≥10 次标记为高频 (hot)。\n"
        "Use this as a pre-filter: query first, if not cached then fall through to LLM reasoning."
    )
    icon: str = "Zap"
    name: str = "rocos_semantic_cache"

    inputs = [
        StrInput(
            name="mode",
            display_name="模式",
            info="query: 查询缓存; learn: 学习新映射; stats: 查看统计",
            value="query",
        ),
        StrInput(
            name="intent",
            display_name="语义指令",
            info="用户的自然语言指令，如 '往右一点点'、'往上'",
            value="",
        ),
        StrInput(
            name="action",
            display_name="动作类型 (learn模式)",
            info="对应的 API 动作: MoveL, MoveJ, JogStart, ...",
            value="",
        ),
        StrInput(
            name="params_json",
            display_name="参数 (learn模式, JSON)",
            info="对应的 API 参数 JSON",
            value="{}",
        ),
        StrInput(
            name="memory_dir",
            display_name="存储目录",
            value=DEFAULT_MEMORY_DIR,
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="Cache Result", name="result", method="process"),
    ]

    def process(self) -> Data:
        store = MemoryStore(os.path.join(self.memory_dir, DEFAULT_MEMORY_FILE))
        mode = self.mode.strip().lower()

        if mode == "query":
            return self._do_query(store)

        elif mode == "learn":
            return self._do_learn(store)

        elif mode == "stats":
            return self._do_stats(store)

        return Data(text=f"未知模式: {mode}，支持 query / learn / stats", data={})

    def _do_query(self, store: MemoryStore) -> Data:
        intent = self.intent.strip()
        if not intent:
            return Data(text="请输入语义指令", data={"cached": False})

        hit = store.cache_query(intent)
        if hit:
            freq = hit.get("frequency", 0)
            action = hit.get("action", {})
            text = (
                f"⚡ 缓存命中! (频次={freq}, 成功率={hit.get('success_count',0)}/{freq})\n"
                f"语义: '{intent}' → {json.dumps(action, ensure_ascii=False)}\n"
                f"置信度: {hit['confidence']:.0%}\n"
                f"预计响应: 0.5s (跳过LLM，走SafeExecutor)"
            )
            self.status = f"命中: {intent} (×{freq})"
            return Data(text=text, data=hit)

        text = f"🔍 缓存未命中: '{intent}'\n→ 交给 LLM 推理 (预计 8s)"
        self.status = f"未命中: {intent}"
        return Data(text=text, data={"cached": False, "intent": intent})

    def _do_learn(self, store: MemoryStore) -> Data:
        intent = self.intent.strip()
        action_name = self.action.strip()
        if not intent:
            return Data(text="learn 模式需要 intent", data={})

        try:
            params = json.loads(self.params_json) if self.params_json else {}
        except json.JSONDecodeError:
            params = {"raw": self.params_json}

        store.cache_learn(intent, action_name, params)

        # 查当前频次
        hit = store.cache_query(intent)
        freq = hit.get("frequency", 0) if hit else 0
        hot = "🔥 高频" if freq >= 10 else ("⚡ 缓存就绪" if freq >= 3 else "🌱 学习中")
        text = f"{hot}: '{intent}' → {json.dumps(params, ensure_ascii=False)} (频次={freq})"
        self.status = text[:100]
        return Data(text=text, data={"intent": intent, "action": params, "frequency": freq})

    def _do_stats(self, store: MemoryStore) -> Data:
        cs = store.cache_stats()
        data = store._load()
        cache = data.get("semantic_cache", {})

        lines = [f"语义缓存统计: {cs['total_intents']} 个意图, {cs['hot_intents']} 个高频"]
        if cache:
            lines.append("\n意图列表 (按频率排序):")
            sorted_items = sorted(cache.items(), key=lambda x: x[1].get("frequency", 0), reverse=True)
            for intent, entry in sorted_items[:15]:
                freq = entry.get("frequency", 0)
                success = entry.get("success_count", 0)
                marker = "🔥" if freq >= 10 else ("⚡" if freq >= 3 else "🌱")
                action = json.dumps(entry.get("action", {}), ensure_ascii=False)
                lines.append(f"  {marker} ×{freq:3d}(ok{success}) '{intent}' → {action[:80]}")

        text = "\n".join(lines)
        self.status = f"缓存: {cs['total_intents']}个意图, {cs['hot_intents']}个高频"
        return Data(text=text, data=cs)

"""
ROCOS 自进化记忆系统 — 越用越聪明，越用越快

四层闭环:
  1. RocosSemanticCache — 语义→指令缓存 (高频指令跳过LLM，响应 8s→0.5s)
  2. RocosMemory        — 记录每次动作 (执行记忆)
  3. RocosReflect       — 分析历史提取模式 (自省)
  4. RocosKnowledge     — 累积可查询的经验规则 (知识库)

存储后端: 本地 JSON 文件 (零外部依赖)
路径: {memory_dir}/rocos_memory.json  (默认 /tmp/rocos_memory/rocos_memory.json)
"""

import json
import os
import time
from pathlib import Path
from typing import Optional
from langflow.custom import Component
from langflow.io import Output, StrInput, FloatInput
from langflow.schema import Data
import json
import urllib.error
import urllib.parse
import urllib.request
from typing import Optional


def _error(code: int, message: str) -> dict:
    return {"success": False, "code": code, "message": message, "data": None}


def _url(base_url: str, path: str, params: Optional[dict] = None) -> str:
    url = f"{base_url.rstrip('/')}{path}"
    if params:
        query = urllib.parse.urlencode({k: v for k, v in params.items() if v is not None})
        if query:
            url = f"{url}?{query}"
    return url


def _decode_json(body: str) -> dict:
    if not body:
        return {}
    return json.loads(body)


def _parse_http_error(e: urllib.error.HTTPError) -> dict:
    try:
        body = e.read().decode("utf-8")
        parsed = _decode_json(body)
        if isinstance(parsed, dict):
            parsed.setdefault("success", False)
            parsed.setdefault("code", e.code)
            parsed.setdefault("message", e.reason)
            return parsed
    except Exception:
        pass
    return _error(e.code, f"HTTP {e.code}: {e.reason}")


def _rocos_request(
    base_url: str, path: str, method: str = "GET",
    body: Optional[dict] = None, params: Optional[dict] = None,
    expect_json: bool = True, timeout: float = 30.0,
):
    url = _url(base_url, path, params)
    data = json.dumps(body).encode("utf-8") if body is not None else None
    headers = {"Accept": "application/json" if expect_json else "*/*"}
    if data is not None:
        headers["Content-Type"] = "application/json"
    try:
        req = urllib.request.Request(url, data=data, headers=headers, method=method)
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            text = resp.read().decode("utf-8")
            return _decode_json(text) if expect_json else text
    except urllib.error.HTTPError as e:
        return _parse_http_error(e)
    except urllib.error.URLError as e:
        return _error(-1, f"网络错误: {e}")
    except json.JSONDecodeError as e:
        return _error(-2, f"JSON 解析错误: {e}")


def _rocos_get(base_url: str, path: str, params: Optional[dict] = None) -> dict:
    return _rocos_request(base_url, path, method="GET", params=params, timeout=10.0)


def _rocos_post(base_url: str, path: str, body: Optional[dict] = None) -> dict:
    return _rocos_request(base_url, path, method="POST", body=body or {})


def _rocos_delete(base_url: str, path: str, params: Optional[dict] = None) -> dict:
    return _rocos_request(base_url, path, method="DELETE", params=params)


def _rocos_text(base_url: str, path: str, params: Optional[dict] = None) -> str:
    return _rocos_request(base_url, path, method="GET", params=params, expect_json=False, timeout=10.0)


def parse_float_list(text: str, expected_len: Optional[int] = None) -> list[float]:
    values = [float(x.strip()) for x in text.split(",") if x.strip()]
    if expected_len is not None and len(values) != expected_len:
        raise ValueError(f"expected {expected_len} values, got {len(values)}")
    return values


DEFAULT_MEMORY_DIR = "/tmp/rocos_memory"
DEFAULT_MEMORY_FILE = "rocos_memory.json"


# ---- 内存存储引擎 ----

class MemoryStore:
    """本地 JSON 文件存储，零依赖"""

    def __init__(self, filepath: str):
        self.filepath = filepath
        Path(os.path.dirname(filepath)).mkdir(parents=True, exist_ok=True)
        if not os.path.exists(filepath):
            self._save({"executions": [], "patterns": [], "stats": {
                "total_motions": 0, "errors": 0, "recoveries": 0,
                "total_distance": 0.0, "favored_positions": [],
            }})

    def _load(self) -> dict:
        try:
            with open(self.filepath) as f:
                return json.load(f)
        except (json.JSONDecodeError, FileNotFoundError):
            return {"executions": [], "patterns": [], "stats": {}}

    def _save(self, data: dict):
        with open(self.filepath, 'w') as f:
            json.dump(data, f, indent=2, ensure_ascii=False)

    def record(self, entry: dict):
        data = self._load()
        data["executions"].append(entry)
        # 只保留最近 200 条
        if len(data["executions"]) > 200:
            data["executions"] = data["executions"][-200:]
        # 更新统计
        stats = data.setdefault("stats", {})
        stats["total_motions"] = stats.get("total_motions", 0) + 1
        if not entry.get("success", True):
            stats["errors"] = stats.get("errors", 0) + 1
        self._save(data)

    def record_recovery(self):
        data = self._load()
        stats = data.setdefault("stats", {})
        stats["recoveries"] = stats.get("recoveries", 0) + 1
        self._save(data)

    def get_recent(self, n: int = 10) -> list:
        data = self._load()
        return data["executions"][-n:]

    def get_stats(self) -> dict:
        return self._load().get("stats", {})

    def add_pattern(self, pattern: dict):
        data = self._load()
        # 去重: 如果已存在相似 pattern 则更新置信度
        for p in data["patterns"]:
            if p.get("name") == pattern.get("name"):
                p["confidence"] = min(1.0, p.get("confidence", 0.5) + 0.15)
                p["count"] = p.get("count", 1) + 1
                self._save(data)
                return
        pattern["count"] = 1
        data["patterns"].append(pattern)
        self._save(data)

    def get_patterns(self) -> list:
        return self._load().get("patterns", [])

    # ---- 语义缓存 ----

    def cache_query(self, intent: str) -> Optional[dict]:
        """查询语义缓存: 命中返回 {action_name, action(template), frequency, confidence, cached}, 否则 None"""
        intent_key = self._normalize_intent(intent)
        data = self._load()
        cache = data.setdefault("semantic_cache", {})

        if intent_key in cache:
            entry = cache[intent_key]
            freq = entry.get("frequency", 0)
            if freq >= 3:
                return {
                    "action_name": entry.get("action_name", ""),
                    "action": entry.get("action", {}),
                    "frequency": freq,
                    "success_count": entry.get("success_count", 0),
                    "failure_count": entry.get("failure_count", 0),
                    "confidence": min(0.99, 0.5 + freq * 0.1),
                    "cached": True,
                }
        return None

    def cache_learn(self, intent: str, action_name: str = "", action_template: Optional[dict] = None):
        """学习: 记录语义→动作模板的映射，增加频率

        action_template 格式:
          {"type": "cartesian_delta", "delta": [0, 0.03, 0, 0, 0, 0], "speed": 0.1}
        """
        intent_key = self._normalize_intent(intent)
        data = self._load()
        cache = data.setdefault("semantic_cache", {})

        template = action_template or {}
        template_key = json.dumps(template, sort_keys=True)

        if intent_key in cache:
            existing = cache[intent_key]
            existing_template = existing.get("action", {})
            if json.dumps(existing_template, sort_keys=True) == template_key:
                existing["frequency"] = existing.get("frequency", 0) + 1
                existing["success_count"] = existing.get("success_count", 0) + 1
                existing["last_used"] = time.strftime("%Y-%m-%dT%H:%M:%S")
            else:
                # 不同模板 → 保留频率更高的
                if existing.get("frequency", 0) < 2:
                    existing["action"] = template
                    existing["action_name"] = action_name
                    existing["frequency"] = 1
                    existing["success_count"] = 1
        else:
            cache[intent_key] = {
                "action_name": action_name,
                "action": template,
                "frequency": 1,
                "success_count": 1,
                "failure_count": 0,
                "first_seen": time.strftime("%Y-%m-%dT%H:%M:%S"),
                "last_used": time.strftime("%Y-%m-%dT%H:%M:%S"),
            }

        self._save(data)

    def cache_stats(self) -> dict:
        """返回缓存统计"""
        data = self._load()
        cache = data.get("semantic_cache", {})
        hot = sum(1 for v in cache.values() if v.get("frequency", 0) >= 5)
        total = len(cache)
        return {"total_intents": total, "hot_intents": hot, "hit_rate": round(hot / max(total, 1), 2)}

    @staticmethod
    def _normalize_intent(text: str) -> str:
        """标准化意图字符串: 去空格、统一方向词"""
        import re
        t = text.strip().lower()
        t = re.sub(r'\s+', '', t)
        # 统一方向语义
        synonyms = {
            '向上': '往上', '向上边': '往上', 'up': '往上',
            '向下': '往下', '向下边': '往下', 'down': '往下',
            '向左': '往左', 'left': '往左',
            '向右': '往右', 'right': '往右',
            '向前': '往前', 'forward': '往前',
            '向后': '往后', 'back': '往后',
        }
        for old, new in synonyms.items():
            t = t.replace(old, new)
        return t

    def get_knowledge_card(self) -> str:
        """生成一张经验卡片 — 给 Agent 做上下文"""
        data = self._load()
        stats = data.get("stats", {})
        patterns = data.get("patterns", [])
        recent = data["executions"][-5:]

        cache = data.get("semantic_cache", {})
        hot = sum(1 for v in cache.values() if v.get("frequency", 0) >= 5)
        card = "## ROCOS 经验累积\n\n"
        card += f"总动作: {stats.get('total_motions', 0)}  |  "
        card += f"错误: {stats.get('errors', 0)}  |  "
        card += f"恢复: {stats.get('recoveries', 0)}\n"
        card += f"语义缓存: {len(cache)} 个意图, {hot} 个高频命中\n\n"

        if patterns:
            card += "### 学到的模式\n"
            for p in sorted(patterns, key=lambda x: x.get("confidence", 0), reverse=True)[:5]:
                card += f"- [{p.get('confidence', 0):.0%}] {p.get('name', '')}: {p.get('advice', '')}\n"

        if recent:
            card += "\n### 最近动作\n"
            for e in reversed(recent[-3:]):
                ts = e.get("timestamp", "")[:19]
                card += f"- [{ts}] {e.get('action', '?')}: {e.get('summary', '')}\n"

        return card


# ---- 1. 执行记忆 ----

class RocosMemory(Component):
    """记录每次机器人动作到持久化存储"""

    display_name: str = "ROCOS 执行记忆"
    description: str = (
        "记录机器人每次动作（运动类型、参数、前后状态、结果）到本地 JSON 文件。"
        "自动累积统计信息（总次数、错误率等）。"
        "Use this tool after every robot action to build an experience database."
    )
    icon: str = "Database"
    name: str = "rocos_memory"

    inputs = [
        StrInput(name="base_url", display_name="API 基础地址", value="http://localhost:8080"),
        StrInput(name="action", display_name="动作类型", info="如 MoveJ, MoveL, JogStart 等", value="MoveL"),
        StrInput(name="params_json", display_name="动作参数 (JSON)", info="动作的参数字典 JSON", value="{}"),
        StrInput(name="summary", display_name="摘要", info="一句话描述做了什么", value=""),
        StrInput(name="memory_dir", display_name="存储目录", value=DEFAULT_MEMORY_DIR, advanced=True),
    ]

    outputs = [
        Output(display_name="Memory Entry", name="entry", method="record_action"),
    ]

    def record_action(self) -> Data:
        # 读当前状态
        state = _rocos_get(self.base_url, "/api/robot/state")
        sdata = state.get("data", {})
        robot_state = sdata.get("robot_state", "UNKNOWN")
        flange = sdata.get("flange", {}).get("position", {})

        # 解析参数
        try:
            params = json.loads(self.params_json) if self.params_json else {}
        except json.JSONDecodeError:
            params = {"raw": self.params_json}

        entry = {
            "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S"),
            "action": self.action,
            "params": params,
            "state_snapshot": {
                "robot_state": robot_state,
                "flange_x": round(flange.get("x", 0), 4),
                "flange_y": round(flange.get("y", 0), 4),
                "flange_z": round(flange.get("z", 0), 4),
            },
            "summary": self.summary or f"{self.action} @ {robot_state}",
            "success": robot_state != "ERROR_STATE",
        }

        store = MemoryStore(os.path.join(self.memory_dir, DEFAULT_MEMORY_FILE))
        store.record(entry)

        stats = store.get_stats()
        text = (
            f"📝 已记录: {entry['summary']}\n"
            f"累计: {stats.get('total_motions', 0)} 次动作, "
            f"{stats.get('errors', 0)} 次错误, "
            f"{stats.get('recoveries', 0)} 次恢复"
        )
        self.status = text[:100]
        return Data(text=text, data=entry)


# ---- 2. 自省分析 ----

class RocosReflect(Component):
    """分析历史记忆，提取模式和改进建议"""

    display_name: str = "ROCOS 经验自省"
    description: str = (
        "分析历史执行记录，自动发现模式: 哪些参数导致失败？哪些目标位置安全？"
        "Use this periodically to let the system learn from past actions."
    )
    icon: str = "BrainCircuit"
    name: str = "rocos_reflect"

    inputs = [
        StrInput(name="memory_dir", display_name="存储目录", value=DEFAULT_MEMORY_DIR, advanced=True),
    ]

    outputs = [
        Output(display_name="Insights", name="insights", method="analyze"),
    ]

    def analyze(self) -> Data:
        store = MemoryStore(os.path.join(self.memory_dir, DEFAULT_MEMORY_FILE))
        recent = store.get_recent(100)
        stats = store.get_stats()

        if not recent:
            return Data(text="暂无历史数据可供分析", data={"patterns": []})

        insights = []

        # 分析 1: 错误模式
        errors = [e for e in recent if not e.get("success", True)]
        if errors:
            # 统计错误前的动作类型
            from collections import Counter
            error_actions = Counter(e.get("action", "?") for e in errors)
            top_error = error_actions.most_common(1)[0]
            insights.append({
                "name": "高频错误动作",
                "advice": f"{top_error[0]} 出现了 {top_error[1]} 次错误，下次执行前先确认状态并降低速度",
                "confidence": min(0.9, top_error[1] / 5),
            })

        # 分析 2: 成功模式 — 最常用位置区域
        successes = [e for e in recent if e.get("success", True)]
        if successes:
            z_values = [e.get("state_snapshot", {}).get("flange_z", 0) for e in successes if "state_snapshot" in e]
            if z_values:
                avg_z = sum(z_values) / len(z_values)
                min_z, max_z = min(z_values), max(z_values)
                insights.append({
                    "name": "安全工作区间",
                    "advice": f"Z 轴安全区间: [{min_z:.3f}, {max_z:.3f}]，均值 {avg_z:.3f}。超出此范围时谨慎",
                    "confidence": 0.7,
                })

        # 分析 3: 恢复率
        if stats.get("errors", 0) > 0:
            recovery_rate = stats.get("recoveries", 0) / stats.get("errors", 0)
            if recovery_rate < 0.5:
                insights.append({
                    "name": "低恢复率",
                    "advice": "错误恢复率低，建议在 Agent 提示词中加入错误恢复流程指引",
                    "confidence": 0.8,
                })

        # 分析 4: 速度趋势
        velocities = []
        for e in recent:
            v = e.get("params", {}).get("velocity", 0)
            if v:
                velocities.append(v)
        if velocities:
            avg_vel = sum(velocities) / len(velocities)
            if avg_vel > 0.5:
                insights.append({
                    "name": "速度偏高",
                    "advice": f"平均速度 {avg_vel:.2f}，建议降低至 0.3 以下提高安全性",
                    "confidence": 0.6,
                })

        # 存储 pattern
        for ins in insights:
            store.add_pattern(ins)

        # 生成报告
        text = "## 自省分析报告\n\n"
        for ins in sorted(insights, key=lambda x: x["confidence"], reverse=True):
            text += f"- [{ins['confidence']:.0%}] {ins['name']}: {ins['advice']}\n"

        if not insights:
            text += "✅ 未发现明显模式，数据量可能不足。继续积累中...\n"

        text += f"\n分析样本: {len(recent)} 条记录"

        self.status = f"发现 {len(insights)} 个模式，覆盖 {len(recent)} 条记录"
        return Data(text=text, data={"patterns": insights, "stats": stats})


# ---- 3. 知识库 ----

class RocosKnowledge(Component):
    """查询累积的经验知识"""

    display_name: str = "ROCOS 经验知识"
    description: str = (
        "查询从历史执行中积累的经验知识: 统计信息、学到的模式、最近动作。"
        "可连接到 Agent 的 context 或 system_prompt，让每次对话都带着历史经验。"
        "Use this tool at the start of a session to load accumulated experience."
    )
    icon: str = "BookOpen"
    name: str = "rocos_knowledge"

    inputs = [
        StrInput(name="memory_dir", display_name="存储目录", value=DEFAULT_MEMORY_DIR, advanced=True),
    ]

    outputs = [
        Output(display_name="Knowledge Card", name="knowledge", method="get_knowledge"),
    ]

    def get_knowledge(self) -> Data:
        store = MemoryStore(os.path.join(self.memory_dir, DEFAULT_MEMORY_FILE))
        card = store.get_knowledge_card()
